<?php require_once __DIR__.'/../includes/functions.php';require_login('parent');if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('/parent/index.php');}verify_csrf();$pdo=db();$uid=current_user()['id'];$action=$_POST['action']??'';try{if($action==='add_child'){$name=trim($_POST['full_name']??'');$dob=$_POST['date_of_birth']??'';$gender=$_POST['gender']??'';if(!$name||!$dob||$dob>date('Y-m-d')||!in_array($gender,['female','male','other'],true))throw new RuntimeException('Enter valid child details.');$s=$pdo->prepare('INSERT INTO children(parent_id,full_name,date_of_birth,gender,guardian_phone,notes) VALUES(?,?,?,?,?,?)');$s->execute([$uid,$name,$dob,$gender,trim($_POST['guardian_phone']??''),trim($_POST['notes']??'')]);flash('Child profile saved successfully.');}elseif($action==='book'){$child=(int)($_POST['child_id']??0);$hospital=(int)($_POST['hospital_id']??0);$vaccine=(int)($_POST['vaccine_id']??0);$date=$_POST['appointment_date']??'';$time=$_POST['appointment_time']??'';$s=$pdo->prepare('SELECT id FROM children WHERE id=? AND parent_id=?');$s->execute([$child,$uid]);if(!$s->fetch())throw new RuntimeException('Please choose one of your own child profiles.');$s=$pdo->prepare("SELECT id FROM hospitals WHERE id=? AND status='active'");$s->execute([$hospital]);if(!$s->fetch())throw new RuntimeException('Choose an active hospital.');$s=$pdo->prepare("SELECT id FROM vaccines WHERE id=? AND status='available'");$s->execute([$vaccine]);if(!$s->fetch())throw new RuntimeException('Choose an available vaccine.');if(!$date||$date<date('Y-m-d')||!$time)throw new RuntimeException('Choose a future date and a valid time.');$s=$pdo->prepare('SELECT status FROM hospital_vaccines WHERE hospital_id=? AND vaccine_id=?');$s->execute([$hospital,$vaccine]);$availability=$s->fetchColumn();if($availability==='unavailable')throw new RuntimeException('This vaccine is currently unavailable at the selected hospital.');$s=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE hospital_id=? AND appointment_date=? AND appointment_time=? AND status IN ('requested','approved')");$s->execute([$hospital,$date,$time]);if((int)$s->fetchColumn()>0)throw new RuntimeException('That hospital time already has a request. Please choose another time.');$s=$pdo->prepare('INSERT INTO bookings(parent_id,child_id,hospital_id,vaccine_id,appointment_date,appointment_time,parent_note) VALUES(?,?,?,?,?,?,?)');$s->execute([$uid,$child,$hospital,$vaccine,$date,$time,trim($_POST['parent_note']??'')]);flash('Appointment request sent. You can track its status below.');}else throw new RuntimeException('Unknown action.');}catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'Could not save the request. Please check the details and try again.','error');}redirect('/parent/index.php');?>
